import React from 'react';

function HeroSection() {
  return (
    <div className="relative w-full h-[480px] bg-zinc-950 flex flex-col items-center justify-center text-center px-4 overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-t from-[#0b090e] via-transparent to-black/60 z-10" />
      <div className="absolute inset-0 opacity-40 bg-cover bg-center" style={{ backgroundImage: `url('https://image.tmdb.org/t/p/original/xOMo8DxID7PBBtT0q1hXo8sN7uG.jpg')` }} />
      
      <div className="relative z-20 max-w-2xl">
        <span className="text-xs uppercase tracking-widest text-purple-400 font-semibold">거대한 서서, 압도적 장엄함</span>
        <h2 className="text-4xl md:text-5xl font-extrabold text-white mt-2 mb-4 tracking-wider">DUNE : PART TWO</h2>
        <div className="flex justify-center gap-3">
          <button className="bg-purple-600 hover:bg-purple-700 text-white text-xs font-bold px-5 py-2.5 rounded-full shadow-lg transition">
            영화 상세 보기
          </button>
          <button className="bg-white/10 hover:bg-white/20 text-white text-xs font-bold px-5 py-2.5 rounded-full backdrop-blur-md transition">
            빠른 예매
          </button>
        </div>
      </div>
    </div>
  );
}

export default HeroSection;
